export const CLOCK_MINUTE_QUANTITIES = Object.fromEntries(Array.from({length:59},(_,i)=>{
  const n=i+1, words=n<=20?HEBREW_NUMBERS[n]:[tens[n-n%10],andOnes[n%10]].filter(Boolean).join(' ');
  return [n,n===1?'דַּקָּה אַחַת':n===2?'שְׁתֵּי דַּקּוֹת':`${words} דַּקּוֹת`];
}));
const plainOnes=['','אחת','שתיים','שלוש','ארבע','חמש','שש','שבע','שמונה','תשע'];
const plainTeens=['עשר','אחת עשרה','שתים עשרה','שלוש עשרה','ארבע עשרה','חמש עשרה','שש עשרה','שבע עשרה','שמונה עשרה','תשע עשרה'];
const plainTens={20:'עשרים',30:'שלושים',40:'ארבעים',50:'חמישים'};
export const CLOCK_MINUTE_LABELS = Object.fromEntries(Array.from({length:59},(_,i)=>{
  const n=i+1,words=n<10?plainOnes[n]:n<20?plainTeens[n-10]:[plainTens[n-n%10],n%10?'ו'+plainOnes[n%10]:''].filter(Boolean).join(' ');
  return[n,n===1?'דקה אחת':n===2?'שתי דקות':words+' דקות'];
}));
for(const [n,text] of Object.entries(CLOCK_MINUTE_QUANTITIES)) if(![15,30,45].includes(Number(n))) CLOCK_SCHOOL_SCRIPTS[`school-minutes-${n}`]=text;

